79	const handleReceivedMessage = async (
80	  message: FirebaseMessagingTypes.RemoteMessage,
81	) => {
82	  const data = message.data as unknown as NotificationData;
83	  if (!data) return;
84	
85	  // Skip notifications for own messages (works in both foreground and background)
86	  const currentUserId = getCurrentUserId();
87	  if (currentUserId && data.sender === currentUserId) return;
88	
89	  const senderName = data.sender_display_name || data.sender || "Unknown";
90	
91	  // Route unencrypted call events directly to CallKit on iOS (no local notification needed)
92	  const isCallOnIOS =
93	    Platform.OS === "ios" &&
94	    (data.type === "m.call.invite" ||
95	      data.type === "m.call.member" ||
96	      data.type === "m.rtc.notification");
97	
98	  if (isCallOnIOS) {
99	    if (CallKitService.isRingingForRoom(data.room_id)) return;
100	    CallKitService.displayIncomingCall({
101	      roomId: data.room_id,
102	      roomName: data.room_name || senderName,
103	      senderDisplayName: senderName,
104	    });
105	    return;
106	  }
107	
108	  const notificationId = message.messageId || `msg_${Date.now()}`;
109	  const formattedMessage = formatLocalPushNotificationMessage(data);
110	  if (!formattedMessage) return;
111	
112	  // Decrypt encrypted messages, then check if it's a call or a regular message
113	  if (data.type === "m.room.encrypted" && data.room_id && data.event_id) {
114	    try {
115	      const initialized = await ensureServiceInitialized();
116	      if (!initialized) return;
117	
118	      // Single SDK round-trip — all checks below are synchronous on the result
119	      const { item, filteredOut } =
120	        await MatrixNotificationService.getNotificationResult(
121	          data.room_id,
122	          data.event_id,
123	        );
124	
125	      // Suppress events the SDK filtered out via push rules (e.g. m.call.hangup on call decline)
126	      if (filteredOut || !item) return;
127	
128	      // Route decrypted call invites to CallKit on iOS
129	      if (Platform.OS === "ios" && isNotificationItemCallInvite(item)) {
130	        if (CallKitService.isRingingForRoom(data.room_id)) return;
131	        const roomName = RoomService.getRoomInfo(data.room_id)?.displayName();
132	        CallKitService.displayIncomingCall({
133	          roomId: data.room_id,
134	          roomName: roomName || data.room_name || senderName,
135	          senderDisplayName: senderName,
136	        });
137	        return;
138	      }
139	
140	      // Suppress all other call-related events (Answer, Hangup, Candidates) on all platforms
141	      if (isNotificationItemAnyCallEvent(item)) return;
142	
143	      // Suppress protocol-level verification steps (Start, Accept, Key, Mac, Cancel, Done)
144	      if (isNotificationItemVerificationStep(item)) return;
145	
146	      if (isCurrentlyViewingRoom(data.room_id)) return;
147	
148	      const roomName = RoomService.getRoomInfo(data.room_id)?.displayName();
149	      const decryptedContent = getNotificationItemContent(item);
150	
151	      // Cancel the NSE fallback "New message" before showing the decrypted content
152	      await NotifeeService.cancelRoomNotifications(data.room_id);
153	      await NotifeeService.create({
154	        title: roomName || formattedMessage.title,
155	        message: decryptedContent
156	          ? `${senderName}: ${decryptedContent}`
157	          : formattedMessage.message,
158	        id: notificationId,
159	        data: { room_id: data.room_id },
160	      });
161	    } catch (error) {
162	      console.error("[Push] Failed to decrypt:", error);
163	    }
164	    return;
165	  }
166	
167	  // Non-encrypted messages — show directly
168	  if (
169	    formattedMessage.room_id &&
170	    isCurrentlyViewingRoom(formattedMessage.room_id)
171	  ) {
172	    return;
173	  }
174	
175	  await NotifeeService.create({
176	    title: formattedMessage.title,
177	    message: formattedMessage.message,
178	    id: notificationId,
179	    data: { room_id: formattedMessage.room_id },
180	  });
